ALTER TABLE public.avisos ADD COLUMN departamentos_ids text[] NOT NULL DEFAULT '{}';
COMMENT ON COLUMN public.avisos.departamentos_ids IS 'Empty array targets all active professionals; otherwise targets synchronized current departments. Immutable after publication.';
CREATE OR REPLACE FUNCTION public.aviso_para_usuario(_aviso_id uuid,_usuario_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_active_user(_usuario_id) AND EXISTS(SELECT 1 FROM public.avisos a WHERE a.id=_aviso_id AND (cardinality(a.departamentos_ids)=0 OR EXISTS(SELECT 1 FROM public.profissional_departamento pd WHERE pd.usuario_id=_usuario_id AND pd.departamento_id=ANY(a.departamentos_ids)))); $$;
REVOKE ALL ON FUNCTION public.aviso_para_usuario(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.aviso_para_usuario(uuid,uuid) TO authenticated;
CREATE FUNCTION public.avisos_validar_destinatarios() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF TG_OP='UPDATE' AND OLD.publicar_em<=now() AND NEW.departamentos_ids IS DISTINCT FROM OLD.departamentos_ids THEN RAISE EXCEPTION 'Os destinatários não podem mudar após a publicação'; END IF;
IF NEW.tipo<>'comum' AND cardinality(NEW.departamentos_ids)>0 THEN RAISE EXCEPTION 'Insider e compilado são destinados a todos os profissionais'; END IF;
IF EXISTS(SELECT 1 FROM unnest(NEW.departamentos_ids) x(id) WHERE x.id IS NULL OR NOT EXISTS(SELECT 1 FROM public.departamentos_portal d WHERE d.id=x.id)) THEN RAISE EXCEPTION 'Selecione departamentos válidos'; END IF;
NEW.departamentos_ids := ARRAY(SELECT DISTINCT id FROM unnest(NEW.departamentos_ids) x(id) ORDER BY id);
RETURN NEW; END $$;
CREATE TRIGGER avisos_validar_destinatarios BEFORE INSERT OR UPDATE ON public.avisos FOR EACH ROW EXECUTE FUNCTION public.avisos_validar_destinatarios();
CREATE FUNCTION public.departamentos_destinatarios_avisos() RETURNS TABLE(id text,nome text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT d.id,d.nome FROM public.departamentos_portal d WHERE public.tem_permissao('avisos.publicar') OR public.tem_permissao('avisos.confirmacao') OR public.tem_permissao('avisos.gerenciar') ORDER BY d.nome; $$;
REVOKE ALL ON FUNCTION public.departamentos_destinatarios_avisos() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.departamentos_destinatarios_avisos() TO authenticated;
CREATE OR REPLACE FUNCTION public.aviso_disponivel(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.aviso_para_usuario(_id,auth.uid()) AND EXISTS(SELECT 1 FROM public.avisos a WHERE a.id=_id AND (public.aviso_vigente(a.publicar_em,a.expira_em,a.arquivado_em) OR (a.exige_confirmacao AND a.publicar_em<=now() AND a.arquivado_em IS NULL AND NOT EXISTS(SELECT 1 FROM public.avisos_confirmacoes c WHERE c.aviso_id=a.id AND c.usuario_id=auth.uid())))); $$;
ALTER POLICY "Cada um grava as proprias leituras" ON public.avisos_leituras WITH CHECK(usuario_id=auth.uid() AND public.aviso_disponivel(aviso_id));
CREATE OR REPLACE FUNCTION public.marcar_todos_avisos_lidos() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN IF NOT public.is_active_user(auth.uid()) THEN RETURN 0; END IF; INSERT INTO public.avisos_leituras(aviso_id,usuario_id) SELECT a.id,auth.uid() FROM public.avisos a WHERE NOT a.exige_confirmacao AND public.aviso_disponivel(a.id) ON CONFLICT DO NOTHING; GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
CREATE OR REPLACE FUNCTION public.acompanhamento_aviso(_aviso_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE resultado jsonb; BEGIN
IF NOT public.tem_permissao('avisos.confirmacao') OR NOT EXISTS(SELECT 1 FROM public.avisos a WHERE a.id=_aviso_id AND a.exige_confirmacao AND public.gere_aviso(a.autor_id,a.perfil_id)) THEN RAISE EXCEPTION 'Sem permissão para acompanhar este aviso'; END IF;
SELECT jsonb_build_object('titulo',a.titulo,'pessoas',coalesce((SELECT jsonb_agg(jsonb_build_object('id',p.id,'nome',coalesce(nullif(p.full_name,''),p.email),'confirmado_em',c.confirmado_em) ORDER BY p.full_name,p.email) FROM public.profiles p LEFT JOIN public.avisos_confirmacoes c ON c.usuario_id=p.id AND c.aviso_id=a.id WHERE public.aviso_para_usuario(a.id,p.id)),'[]'::jsonb)) INTO resultado FROM public.avisos a WHERE a.id=_aviso_id; RETURN resultado; END $$;
CREATE OR REPLACE FUNCTION public.avisos_enviados_confirmacao() RETURNS TABLE(id uuid,titulo text,mensagem text,perfil_id uuid,perfil_nome text,autor_id uuid,autor_nome text,publicar_em timestamptz,expira_em timestamptz,editado_em timestamptz,arquivado_em timestamptz,lidos bigint,ativos bigint,tipo text,exige_confirmacao boolean)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT a.id,a.titulo,a.mensagem,a.perfil_id,p.nome,a.autor_id,coalesce(nullif(pr.full_name,''),pr.email,''),a.publicar_em,a.expira_em,a.editado_em,a.arquivado_em,CASE WHEN a.exige_confirmacao THEN (SELECT count(*) FROM public.avisos_confirmacoes c WHERE c.aviso_id=a.id AND public.aviso_para_usuario(a.id,c.usuario_id)) ELSE (SELECT count(*) FROM public.avisos_leituras l WHERE l.aviso_id=a.id AND public.aviso_para_usuario(a.id,l.usuario_id)) END,(SELECT count(*) FROM public.profiles u WHERE public.aviso_para_usuario(a.id,u.id)),a.tipo,a.exige_confirmacao FROM public.avisos a JOIN public.perfis p ON p.id=a.perfil_id LEFT JOIN public.profiles pr ON pr.id=a.autor_id WHERE public.gere_aviso(a.autor_id,a.perfil_id) ORDER BY a.publicar_em DESC LIMIT 200 $$;
CREATE FUNCTION public.avisos_enviados_destinatarios() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(to_jsonb(e)||jsonb_build_object('departamentos_ids',a.departamentos_ids) ORDER BY e.publicar_em DESC),'[]'::jsonb) FROM public.avisos_enviados_confirmacao() e JOIN public.avisos a ON a.id=e.id; $$;
REVOKE ALL ON FUNCTION public.avisos_enviados_destinatarios() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.avisos_enviados_destinatarios() TO authenticated;
CREATE OR REPLACE FUNCTION public.listar_avisos(_so_nao_lidos boolean DEFAULT false,_limite integer DEFAULT 20,_deslocamento integer DEFAULT 0) RETURNS TABLE(id uuid,titulo text,mensagem text,perfil_nome text,publicar_em timestamptz,expira_em timestamptz,editado_em timestamptz,lido boolean,tipo text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT a.id,a.titulo,a.mensagem,a.perfil_nome,a.publicar_em,a.expira_em,a.editado_em,a.lido,a.tipo FROM public.listar_avisos_confirmacao(_so_nao_lidos,_limite,_deslocamento) a; $$;
CREATE OR REPLACE FUNCTION public.avisos_enviados() RETURNS TABLE(id uuid,titulo text,mensagem text,perfil_id uuid,perfil_nome text,autor_id uuid,autor_nome text,publicar_em timestamptz,expira_em timestamptz,editado_em timestamptz,arquivado_em timestamptz,lidos bigint,ativos bigint,tipo text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT a.id,a.titulo,a.mensagem,a.perfil_id,a.perfil_nome,a.autor_id,a.autor_nome,a.publicar_em,a.expira_em,a.editado_em,a.arquivado_em,a.lidos,a.ativos,a.tipo FROM public.avisos_enviados_confirmacao() a; $$;